/* src/styles.css */
:root {
  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "PingFang SC",
    "Microsoft YaHei",
    sans-serif;
  color: #232631;
  background: #f6f7f9;
  font-synthesis: none;
  --accent:#625de8;
  --muted:#808695;
  --line:#e8e9ef;
  --soft:#f0efff;
  --ink:#232631;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
button,
input,
select,
textarea {
  font: inherit;
  font-size: 13px;
}
button,
a,
input,
select,
textarea {
  -webkit-tap-highlight-color: transparent;
}
button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 13px;
  background: #fff;
  color: var(--ink);
  border: 1px solid #dde0e9;
  border-radius: 7px;
  cursor: pointer;
  line-height: 1.4;
  transition: background .15s, border-color .15s;
}
button:hover {
  background: #f7f7fc;
  border-color: #c6c5da;
}
button:disabled {
  cursor: not-allowed;
  opacity: .42;
}
a {
  color: inherit;
  text-decoration: none;
}
button:focus-visible,
a:focus-visible {
  outline: 3px solid #bdb9fb;
  outline-offset: 3px;
}
input:focus,
select:focus,
textarea:focus {
  outline: 2px solid #bdb9fb;
  outline-offset: 1px;
}
input,
select,
textarea {
  color: var(--ink);
  background: #fff;
  border: 1px solid #dce0e9;
  border-radius: 7px;
  padding: 10px 12px;
  max-width: 100%;
}
select {
  padding-right: 25px;
}
input[type=checkbox] {
  accent-color: var(--accent);
  width: 16px;
  height: 16px;
}
h1,
h2,
h3,
h4,
p {
  margin: 0;
}
h1 {
  font-size: 28px;
  letter-spacing: -.6px;
  line-height: 1.45;
  font-weight: 650;
}
h2 {
  font-size: 18px;
  line-height: 1.5;
  font-weight: 620;
}
h3 {
  font-size: 18px;
  line-height: 1.5;
}
h4 {
  font-size: 15px;
  font-weight: 600;
}
p {
  line-height: 1.8;
}
small {
  font-size: 12px;
}
svg {
  flex-shrink: 0;
  stroke-width: 1.65;
}
button.primary {
  background: var(--accent);
  border-color: var(--accent);
  color: white;
  box-shadow: 0 2px 3px #625de813;
}
button.primary:hover {
  background: #534ed3;
}
button.icon-button {
  padding: 7px;
  background: transparent;
  border-color: transparent;
}
.icon-button svg {
  width: 19px;
  height: 19px;
}
.text-button,
.source-link {
  border: 0;
  background: transparent;
  padding: 5px 0;
  box-shadow: none !important;
}
.text-button {
  color: var(--muted);
  font-size: 12px;
}
.source-link {
  color: var(--accent);
  font-size: 12px;
  text-align: left;
  justify-content: flex-start;
}
.muted,
.note {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.8;
}
.note {
  margin: 20px 0 0;
}
.tag {
  color: var(--accent);
  background: #eeecff;
  border-radius: 4px;
  font-size: 11px;
  padding: 3px 6px;
  display: inline-flex;
}
.app-shell {
  display: flex;
  min-height: 100vh;
}
.global-sidebar {
  width: 210px;
  flex: 0 0 210px;
  background: #f0f1f5;
  padding: 24px 15px 18px;
  position: fixed;
  inset: 0 auto 0 0;
  display: flex;
  flex-direction: column;
}
.brand {
  display: flex;
  gap: 11px;
  align-items: center;
  margin: 3px 9px 34px;
  font-size: 19px;
  font-weight: 650;
  letter-spacing: -.6px;
}
.brand svg {
  color: var(--accent);
  width: 25px;
  height: 25px;
}
.nav-group-label {
  color: #9298a7;
  font-size: 11px;
  letter-spacing: .5px;
  margin: 0 13px 12px;
}
.business-label {
  margin-top: 28px;
  padding-top: 23px;
  border-top: 1px solid #dedfe7;
}
.global-sidebar nav a,
.sidebar-bottom a {
  display: flex;
  gap: 14px;
  align-items: center;
  padding: 11px 13px;
  margin: 3px 0;
  border-radius: 7px;
  font-size: 13px;
}
.global-sidebar a:hover {
  background: #e8e9f0;
}
.global-sidebar a.active {
  background: #e5e3fb;
  color: #5f58db;
  font-weight: 550;
}
.global-sidebar nav svg,
.sidebar-bottom svg {
  width: 18px;
  height: 18px;
}
.global-sidebar nav small {
  margin-left: auto;
  font-size: 11px;
}
.sidebar-bottom {
  margin-top: auto;
  font-size: 12px;
}
.sidebar-bottom > div {
  display: flex;
  gap: 13px;
  align-items: center;
  padding: 22px 13px 8px;
}
.sidebar-bottom > div svg {
  background: #dddfe7;
  border-radius: 50%;
  padding: 5px;
  width: 28px;
  height: 28px;
  color: #6d7485;
}
.app-shell > main {
  margin-left: 210px;
  width: calc(100% - 210px);
  min-width: 0;
}
.topbar {
  height: 57px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 30px;
  font-size: 12px;
  color: var(--muted);
  gap: 10px;
}
.breadcrumbs {
  display: flex;
  gap: 10px;
  align-items: center;
  min-width: 0;
}
.breadcrumbs a:hover {
  color: var(--accent);
}
.breadcrumbs svg {
  width: 13px;
  height: 13px;
  color: #9ca2ae;
}
.breadcrumbs span:last-child {
  color: #424859;
}
.prototype-note {
  white-space: nowrap;
  font-size: 11px;
}
.main-surface {
  margin: 0 16px 16px 0;
  background: #fff;
  border: 1px solid #eeeff5;
  border-radius: 12px;
  min-height: calc(100vh - 74px);
  overflow: hidden;
  box-shadow: 0 2px 10px #222b4402;
}
.page-pad {
  padding: 40px;
}
.page-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 40px;
}
.page-heading p {
  font-size: 13px;
  color: var(--muted);
  margin-top: 7px;
}
.page-heading > .primary {
  align-self: center;
}
.library-toolbar {
  display: flex;
  align-items: center;
  gap: 20px;
  justify-content: space-between;
  margin-bottom: 18px;
}
.filter-tabs {
  display: flex;
  gap: 7px;
  flex-shrink: 0;
}
.filter-tabs button {
  border: none;
  color: #818695;
  background: transparent;
  font-size: 12px;
  padding: 7px 10px;
}
.filter-tabs .selected {
  color: #534bd8;
  background: #efedff;
}
.table-tools {
  display: flex;
  gap: 8px;
  align-items: center;
}
.search {
  display: flex;
  gap: 7px;
  align-items: center;
  color: #9499a6;
}
.search input {
  width: 210px;
  border: 0;
  background: transparent;
  padding: 7px 0;
  font-size: 12px;
  min-width: 0;
}
.table-heading,
.case-table-row {
  display: grid;
  grid-template-columns: minmax(250px, 2.4fr) minmax(130px, 1.2fr) 95px 100px 18px;
  gap: 16px;
  align-items: center;
  text-align: left;
  width: 100%;
}
.table-heading {
  color: #8e93a1;
  font-size: 11px;
  padding: 13px 14px;
  background: #f8f9fc;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.case-table-row {
  padding: 24px 14px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  font-size: 12px;
  background: white;
}
.case-table-row:hover {
  background: #fafaff;
}
.case-table-row > svg {
  color: #9a9fac;
}
.case-cell {
  display: flex;
  gap: 14px;
  align-items: center;
}
.case-cell > b,
.case-cell b {
  font-size: 14px;
  font-weight: 550;
}
.case-cell small {
  display: block;
  font-size: 11px;
  color: #9196a4;
  margin-top: 7px;
}
.case-file {
  color: #8e89e2;
  background: #f1f0fc;
  padding: 10px;
  border-radius: 8px;
  display: flex;
}
.round-cell {
  color: #72798a;
  font-size: 12px;
}
.deadline {
  color: #737b8d;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.status {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  font-size: 11px;
  white-space: nowrap;
}
.status:before {
  content: "";
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #a9aebb;
}
.status-materials {
  color: #a08045;
}
.status-materials:before {
  background: #d3ac67;
}
.status-strategy {
  color: #7470ce;
}
.status-strategy:before {
  background: #9089e8;
}
.status-review {
  color: #b0845f;
}
.status-draft {
  color: #667eb1;
}
.status-final {
  color: #518975;
}
.status-final:before {
  background: #63a48b;
}
.table-foot {
  display: flex;
  justify-content: space-between;
  color: #999eab;
  font-size: 11px;
  margin-top: 18px;
}
.quiet-banner {
  background: #f7f7fc;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 13px 16px;
  font-size: 12px;
  color: #82879a;
  margin: -18px 0 25px;
}
.case-space {
  padding: 38px 40px;
}
.case-intro {
  display: flex;
  align-items: center;
  gap: 22px;
  margin-bottom: 27px;
}
.case-intro p {
  color: var(--muted);
  font-size: 12px;
  margin-top: 5px;
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.case-emblem {
  display: flex;
  align-items: center;
  justify-content: center;
  background: #f0eeff;
  color: var(--accent);
  width: 58px;
  height: 58px;
  border-radius: 10px;
  flex-shrink: 0;
}
.case-emblem svg {
  width: 28px;
  height: 28px;
}
.case-intro .more {
  margin-left: auto;
  align-self: flex-start;
}
.case-tabs {
  display: flex;
  gap: 19px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 32px;
}
.case-tabs button {
  border: 0;
  background: transparent;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  padding: 12px 10px 14px;
  color: #666d7e;
  font-size: 14px;
  white-space: nowrap;
}
.case-tabs button.active {
  color: var(--accent);
  border-color: var(--accent);
}
.overview-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.9fr) minmax(240px, 1fr);
  gap: 34px;
}
.overview-grid > div > h2 {
  margin-bottom: 17px;
}
.current-work {
  border: 1px solid #bbb6ff;
  background: #fbfaff;
  border-radius: 8px;
  padding: 21px 22px;
}
.current-work > p:first-child {
  font-size: 12px;
  color: #8c8ba1;
}
.current-work h3 {
  font-size: 21px;
  font-weight: 620;
  margin-top: 13px;
  margin-bottom: 7px;
  letter-spacing: -.3px;
}
.current-work > p {
  font-size: 13px;
  color: #858a9a;
}
.current-work > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 24px;
  gap: 10px;
}
.current-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  font-size: 12px;
  background: #edeaff;
  padding: 5px 9px;
  border-radius: 20px;
}
.business-heading {
  margin-top: 32px;
}
.business-links {
  border-top: 1px solid var(--line);
}
.business-links button {
  display: flex;
  width: 100%;
  justify-content: flex-start;
  gap: 24px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  padding: 21px 14px;
}
.business-links button > svg:first-child {
  width: 25px;
  height: 25px;
}
.business-links button > svg:last-child {
  margin-left: auto;
  color: #949ba8;
}
.business-links span {
  text-align: left;
}
.business-links b {
  font-weight: 500;
  font-size: 15px;
}
.business-links small {
  display: block;
  color: #8a91a2;
  margin-top: 6px;
  font-size: 12px;
}
.case-aside {
  border-left: 1px solid var(--line);
  padding-left: 30px;
}
.case-aside h2 {
  margin-bottom: 15px;
}
.case-aside dl {
  margin: 0 0 34px;
  font-size: 12px;
}
.case-aside dl > div {
  display: grid;
  grid-template-columns: 88px 1fr;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
  line-height: 1.5;
}
.case-aside dl > div:last-child {
  border: 0;
}
.case-aside dt {
  color: #9298a5;
}
.case-aside dd {
  margin: 0;
}
.recent-file {
  width: 100%;
  justify-content: flex-start;
  gap: 14px;
  text-align: left;
  padding: 18px 4px;
  border: 0;
  border-top: 1px solid var(--line);
  border-radius: 0;
  font-size: 12px;
}
.recent-file > span {
  flex: 1;
}
.recent-file small {
  display: block;
  font-size: 11px;
  color: #9399a7;
  margin-top: 6px;
}
.recent-file > svg:last-child {
  color: #9aa0ae;
}
.case-aside > .note {
  border-top: 1px solid var(--line);
  padding-top: 25px;
  margin-top: 30px;
}
.focused-space {
  padding: 26px 28px;
}
.focused-space .case-intro {
  gap: 0;
  margin-bottom: 13px;
}
.focused-space .case-intro h1 {
  font-size: 22px;
}
.focused-space .case-emblem {
  display: none;
}
.focused-space .case-intro p {
  font-size: 11px;
}
.focused-space .case-tabs {
  margin-bottom: 0;
}
.case-section {
  padding-top: 4px;
}
.section-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}
.section-heading p {
  margin-top: 6px;
}
.case-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  padding: 16px 0;
}
.case-heading select {
  font-size: 12px;
  padding: 6px 10px;
}
.stepper {
  display: flex;
  margin: 2px 0 28px;
  gap: 10px;
}
.stepper button {
  flex: 1;
  display: flex;
  gap: 10px;
  position: relative;
  padding: 8px 0;
  background: transparent;
  border: 0;
  color: #9da2b0;
  font-size: 12px;
  justify-content: flex-start;
  white-space: nowrap;
}
.stepper button:disabled {
  opacity: .65;
}
.stepper button:after {
  content: "";
  flex: 1;
  height: 1px;
  background: #dce0ea;
  margin-left: 4px;
}
.stepper button:last-child:after {
  display: none;
}
.stepper button > span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border: 1px solid #9aa2b4;
  border-radius: 50%;
  flex-shrink: 0;
}
.stepper .current {
  color: var(--accent);
}
.stepper .current > span {
  border: 5px solid var(--accent);
  outline: 1px solid var(--accent);
  outline-offset: 3px;
}
.stepper .done > span {
  color: white;
  background: var(--accent);
  border: 0;
}
.stepper .done:after {
  background: #aba6ed;
}
.stepper .done {
  color: #777b8b;
}
.material-list,
.material-table {
  border-top: 1px solid var(--line);
}
.material-row,
.material-table button {
  width: 100%;
  display: flex;
  gap: 17px;
  justify-content: flex-start;
  text-align: left;
  padding: 19px 13px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}
.material-row > span:first-of-type,
.material-table button > span:first-of-type {
  flex: 1;
  font-size: 13px;
}
.material-row small,
.material-table small {
  display: block;
  font-size: 11px;
  color: var(--muted);
  margin-top: 4px;
}
.material-table b {
  font-weight: 500;
}
.ready {
  display: flex;
  gap: 6px;
  align-items: center;
  color: #729784;
  font-size: 11px;
}
.material-row > svg:last-child,
.material-table button > svg:last-child {
  color: #a0a7b4;
}
.action-bar {
  display: flex;
  gap: 18px;
  align-items: center;
  justify-content: space-between;
  margin-top: 28px;
  border-top: 1px solid var(--line);
  padding-top: 20px;
}
.checkbox {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 12px;
  line-height: 1.6;
}
.job-banner {
  background: #f1efff;
  border: 1px solid #dad6fd;
  padding: 13px 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin: 0 0 25px;
  font-size: 12px;
}
.job-banner > span {
  display: flex;
  gap: 8px;
  align-items: center;
}
.job-banner i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
}
.pulse {
  animation: pulse 1.1s infinite alternate;
}
@keyframes pulse {
  to {
    opacity: .3;
  }
}
.analysis-summary {
  font-size: 13px;
  color: #696f80;
  max-width: 800px;
}
.strategies {
  margin: 20px 0 30px;
  border-top: 1px solid var(--line);
}
.strategy {
  display: flex;
  align-items: center;
  gap: 23px;
  border-bottom: 1px solid var(--line);
  padding: 25px 10px;
}
.strategy-number {
  color: #b5b2ce;
  font-size: 21px;
  font-weight: 300;
  align-self: flex-start;
}
.strategy > div {
  flex: 1;
}
.strategy p {
  font-size: 12px;
  color: #858b99;
  margin: 8px 0;
}
.strategy > button {
  font-size: 12px;
  white-space: nowrap;
}
.discussion {
  border: 1px solid var(--line);
  border-radius: 9px;
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  background: white;
}
.discussion .section-heading {
  padding: 13px 15px;
  border-bottom: 1px solid var(--line);
  margin: 0;
}
.discussion select {
  border: 0;
  background: transparent;
  font-size: 12px;
  padding: 4px 6px;
  min-width: 0;
}
.messages {
  flex: 1;
  padding: 20px 16px;
  min-height: 150px;
  max-height: 440px;
  overflow: auto;
}
.message {
  font-size: 12px;
  margin-bottom: 20px;
}
.message b {
  font-size: 10px;
  color: #8d93a2;
  display: block;
  font-weight: 500;
  margin-bottom: 6px;
}
.message p {
  background: #f5f6f9;
  padding: 12px 14px;
  border-radius: 8px;
  white-space: pre-wrap;
  line-height: 1.9;
}
.message.user {
  margin-left: 25px;
}
.message.user p {
  background: #eeecfd;
  color: #625b91;
}
.composer {
  margin: 14px;
  border: 1px solid #e0e2ec;
  border-radius: 8px;
}
.composer textarea {
  border: 0;
  resize: vertical;
  min-height: 78px;
  width: 100%;
  padding: 12px;
  font-size: 12px;
  line-height: 1.7;
  display: block;
}
.composer > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 10px 6px;
  gap: 8px;
}
.composer .muted {
  font-size: 10px;
}
.editor-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  border-radius: 8px 8px 0 0;
  background: #f5f6fa;
  border: 1px solid var(--line);
  margin-bottom: 0;
}
.editor-toolbar select {
  border: 0;
  background: transparent;
  margin-right: auto;
  font-size: 12px;
}
.editor-toolbar button {
  font-size: 11px;
  padding: 7px 10px;
}
.draft-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.8fr) minmax(260px, 1fr);
  gap: 14px;
